import{z as l,x as n,o,c as d,q as E,j as s,D as e,d as r,s as i,S as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"别名分析","description":"","frontmatter":{"title":"别名分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/alias-analysis.md","filePath":"cs/alias-analysis.md","lastUpdated":1791413859000}'),c={name:"cs/alias-analysis.md"};function B(p,a,C,h,_,u){const t=n("Mermaid");return o(),d("div",null,[a[2]||(a[2]=E('<h1 id="别名分析" tabindex="-1">别名分析 <a class="header-anchor" href="#别名分析" aria-label="Permalink to &quot;别名分析&quot;">​</a></h1><div class="epigraph"><p>两次访存是否可能指向同一对象，决定 load 能否外提、store 能否换序。分析必须可靠：把「可能别名」说成「不别名」会改语义。</p><footer>—— 据龙书 12.4 指针别名；Muchnick；ISO C `restrict`；Wilson and Lam 对照整理</footer></div><p>上一课<a href="/cs/natural-loops">自然循环</a>圈出循环体，但循环里的 load/store 到底指向哪个对象还说不清。缺口是<strong>指针</strong>：C 的 <code>*p</code> 与 <code>*q</code>。别名分析给出 Must / May / No。主干优化默认保守 May。本课钉分类与语言规则（类型别名、<code>restrict</code>），具体 points-to 下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LICM、向量化、DCE 对 store 都问：中间有没有对同一地址的写。无分析则任何 store 杀死所有 load 的可用。缺口是<strong>别名查询接口</strong>，不是调度。</p><p><span class="marginnote">术语翻译：Must／May／No 是三档答案——Must「这两个指针一定指向同一地址」，May「可能指向（编译器无法排除）」，No「一定不同」。优化器只把 No 当通行证：说 May 只是放弃优化，把真正的别名说成 No 就会编译出错误程序。</span></p><p>C：不同基本类型默认不别名（strict aliasing），<code>char*</code> 例外。打破规则是 UB，优化可当不别名——<a href="/cs/undefined-behavior-opt">UB 课</a>。<code>restrict</code> 是程序员承诺。</p><h3 id="may-不是「运行时有时别名」" tabindex="-1">May 不是「运行时有时别名」 <a class="header-anchor" href="#may-不是「运行时有时别名」" aria-label="Permalink to &quot;May 不是「运行时有时别名」&quot;">​</a></h3><p>May 是静态不知道。Must 是必同。查询 API：<code>alias(p,q) ∈ {No, May, Must}</code>。优化只用 No 当许可。</p><p><span class="marginnote">龙书指针分析导引。ISO C 别名规则。Fortran 默认不别名数组参数。本课不写 Steensgaard 算法，下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>基线：按类型、按分配点（栈槽互异、malloc 不重叠除非语言允许）、按 <code>restrict</code>。字段敏感：结构体不同字段可不别名。再接到 points-to 图。</p><p><span class="marginnote">直觉类比：<code>restrict</code> 是程序员向编译器立的字据——「在这个作用域里，我保证通过这些指针写内存互不重叠」。有了字据编译器才敢把 load 提到 store 之前；字据造假（指针真重叠了）就是未定义行为，坏结果不报错、直接算错。</span></p>',13)),(o(),s(A,null,{default:e(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%A4%E6%AC%A1%E8%AE%BF%E5%AD%98%22%5D%20--%3E%20TY%5B%22%E7%B1%BB%E5%9E%8B%20%2F%20restrict%22%5D%0A%20%20Q%20--%3E%20PT%5B%22%E6%8C%87%E5%90%91%E9%9B%86%22%5D%0A%20%20TY%20--%3E%20A%5B%22No%20%2F%20May%20%2F%20Must%22%5D%0A%20%20PT%20--%3E%20A%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>与所有权：借用检查在源级已禁某些别名；降到 IR 后分析仍要跑，因 <code>unsafe</code> 与 FFI。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过程间：callee 是否写 <code>*p</code> 要摘要。无摘要则 May 写全局。不要把 Java 的类型精确当 C 的 <code>char*</code> 规则。</p><p>TBAA（type-based alias analysis）把语言规则编进 IR 元数据；错误的元数据 = 错误优化。</p><p>别名查询的三种答案各自打开不同的优化窗口，也可能什么都打不开：</p>',5)),(o(),s(A,null,{default:e(()=>[i(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22%E4%BC%98%E5%8C%96%E6%83%B3%E6%94%B9%E5%86%99%E4%B8%A4%E6%AC%A1%E8%AE%BF%E5%AD%98%EF%BC%9A%E5%A4%96%E6%8F%90%20%2F%20%E6%8D%A2%E5%BA%8F%20%2F%20%E5%88%A0%E5%86%97%E4%BD%99%22%5D%20--%3E%20ASK%7B%22alias(p%2C%20q)%20%E8%BF%94%E5%9B%9E%E5%93%AA%E4%B8%80%E6%A1%A3%EF%BC%9F%22%7D%0A%20%20ASK%20--%3E%7C%22No%EF%BC%9A%E4%B8%80%E5%AE%9A%E4%B8%8D%E5%90%8C%E5%9C%B0%E5%9D%80%22%7C%20GO%5B%22%E6%94%BE%E5%BF%83%E6%94%B9%EF%BC%9A%E5%A4%96%E6%8F%90%E3%80%81%E6%8D%A2%E5%BA%8F%E3%80%81%E5%88%A0%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%AF%BB%22%5D%0A%20%20ASK%20--%3E%7C%22May%EF%BC%9A%E5%8F%AF%E8%83%BD%E7%9B%B8%E5%90%8C%22%7C%20HOLD%5B%22%E4%BF%9D%E5%AE%88%EF%BC%9A%E5%BD%93%E4%BD%9C%E4%BC%9A%E5%86%99%E5%90%8C%E4%B8%80%E5%A4%84%EF%BC%8C%E6%94%BE%E5%BC%83%E6%94%B9%E5%86%99%22%5D%0A%20%20ASK%20--%3E%7C%22Must%EF%BC%9A%E4%B8%80%E5%AE%9A%E7%9B%B8%E5%90%8C%22%7C%20REPL%5B%22%E5%88%A9%E7%94%A8%E5%AE%83%EF%BC%9A%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%AF%BB%E7%9B%B4%E6%8E%A5%E7%94%A8%E7%AC%AC%E4%B8%80%E6%AC%A1%E7%9A%84%E5%80%BC%22%5D%0A%20%20HOLD%20--%3E%20SAFE%5B%22%E5%AE%81%E5%8F%AF%E6%85%A2%E4%B8%80%E7%82%B9%E4%B9%9F%E4%B8%8D%E6%94%B9%E8%AF%AD%E4%B9%89%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">常见误区：初学者以为「能强转过去就没问题」。C 规定不同基本类型的对象默认不互为别名（strict aliasing），用 <code>int*</code> 去写 <code>float</code> 对象是未定义行为，编译器会据此把你的写入优化掉；唯一例外是 <code>char*</code>，它可以合法查看任何对象的字节。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现 Andersen。后课默认：优化问别名，No 才激进。下一课 Andersen / Steensgaard 指向分析。</p><p>也不把别名当加密侧信道模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>别名查询：No 才允许把两次访存当独立。</li><li>语言规则（TBAA、restrict）是分析的输入。</li><li>可靠优先于精确。</li><li>出处：Aho et al. 龙书；ISO C；Muchnick。</li></ul>',6))])}const D=l(c,[["render",B]]);export{F as __pageData,D as default};
